package ro.leo.visual;
import ro.leo.i18n.L;
import java.io.*;import java.net.*;import java.nio.*;import java.nio.charset.*;import java.util.*;import java.util.zip.*;import javax.xml.parsers.*;import org.w3c.dom.*;
/** Reads local TXT and the EPUB spine. Never extracts archive paths or loads external XML. */
final class BookDocument {
 final ArrayList<String> names=new ArrayList<String>(),chapters=new ArrayList<String>();String title;
 static byte[] bytes(InputStream in,int limit)throws IOException{ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){if(out.size()+n>limit)throw new IOException(L.t("Conținut prea mare"));out.write(b,0,n);}return out.toByteArray();}
 static String utf8(byte[] b)throws IOException{try{String s=StandardCharsets.UTF_8.newDecoder().onMalformedInput(CodingErrorAction.REPORT).decode(ByteBuffer.wrap(b)).toString();return s.startsWith("\ufeff")?s.substring(1):s;}catch(CharacterCodingException e){throw new IOException(L.t("Textul trebuie să fie UTF-8"));}}
 static String path(String base,String href)throws IOException{try{URI u=new URI(href);if(u.isAbsolute()||u.getAuthority()!=null)throw new IOException();String value=u.getPath();if(value==null||value.startsWith("/")||value.contains("\\")||value.indexOf('\0')>=0)throw new IOException();String prefix=base.contains("/")?base.substring(0,base.lastIndexOf('/')+1):"";ArrayList<String> parts=new ArrayList<String>();for(String part:(prefix+value).split("/")){if(part.isEmpty()||part.equals("."))continue;if(part.equals("..")){if(parts.isEmpty())throw new IOException();parts.remove(parts.size()-1);}else{if(part.contains(":"))throw new IOException();parts.add(part);}}String result=String.join("/",parts);if(result.isEmpty())throw new IOException();return result;}catch(URISyntaxException e){throw new IOException(L.t("Cale EPUB invalidă"));}}
 static Document xml(byte[] b)throws Exception{String text=utf8(b);if(text.toUpperCase(Locale.ROOT).contains("<!ENTITY"))throw new IOException(L.t("Declarațiile de entități nu sunt acceptate"));text=text.replaceAll("(?is)<!DOCTYPE\\s+[^\\[>]*>","");if(text.toUpperCase(Locale.ROOT).contains("<!DOCTYPE"))throw new IOException(L.t("DTD intern refuzat"));String[][] entities={{"nbsp","\u00a0"},{"mdash","—"},{"ndash","–"},{"hellip","…"},{"lsquo","‘"},{"rsquo","’"},{"ldquo","“"},{"rdquo","”"},{"copy","©"},{"reg","®"},{"shy","\u00ad"}};for(String[] e:entities)text=text.replace("&"+e[0]+";",e[1]);b=text.getBytes("UTF-8");javax.xml.parsers.SAXParserFactory sf=javax.xml.parsers.SAXParserFactory.newInstance();sf.setNamespaceAware(true);org.xml.sax.XMLReader reader=sf.newSAXParser().getXMLReader();reader.setEntityResolver(new org.xml.sax.EntityResolver(){public org.xml.sax.InputSource resolveEntity(String a,String z)throws org.xml.sax.SAXException{throw new org.xml.sax.SAXException(L.t("Entitate externă refuzată"));}});reader.setContentHandler(new org.xml.sax.helpers.DefaultHandler(){int depth,nodes;public void startElement(String a,String z,String q,org.xml.sax.Attributes attrs)throws org.xml.sax.SAXException{if(++depth>128||++nodes>20000)throw new org.xml.sax.SAXException(L.t("XML prea complex"));}public void endElement(String a,String z,String q){depth--;}});reader.parse(new org.xml.sax.InputSource(new ByteArrayInputStream(b)));DocumentBuilderFactory f=DocumentBuilderFactory.newInstance();f.setNamespaceAware(true);f.setExpandEntityReferences(false);DocumentBuilder parser=f.newDocumentBuilder();parser.setEntityResolver(new org.xml.sax.EntityResolver(){public org.xml.sax.InputSource resolveEntity(String a,String z)throws org.xml.sax.SAXException{throw new org.xml.sax.SAXException(L.t("Entitate externă refuzată"));}});return parser.parse(new ByteArrayInputStream(b));}
 static String first(Document d,String tag){NodeList nodes=d.getElementsByTagNameNS("*",tag);String value=nodes.getLength()==0?"":nodes.item(0).getTextContent().trim();return value.length()>160?value.substring(0,Character.isHighSurrogate(value.charAt(159))?159:160):value;}
 static byte[] entry(ZipFile zip,String name,int limit)throws Exception{ZipEntry e=zip.getEntry(name);if(e==null||e.isDirectory()||e.getSize()>limit)throw new IOException(L.t("Intrare EPUB lipsă sau prea mare"));try(InputStream in=zip.getInputStream(e)){return bytes(in,limit);}}
 static void text(Node n,StringBuilder b,int depth)throws IOException{if(depth>128||b.length()>524288)throw new IOException(L.t("Capitol prea complex"));String name=n.getLocalName();if(name==null)name=n.getNodeName();if(name.equalsIgnoreCase("script")||name.equalsIgnoreCase("style")||name.equalsIgnoreCase("head"))return;if(n.getNodeType()==Node.TEXT_NODE||n.getNodeType()==Node.CDATA_SECTION_NODE){b.append(n.getNodeValue());return;}boolean block=Arrays.asList("p","div","section","h1","h2","h3","li","br","tr").contains(name);if(block)b.append('\n');for(Node child=n.getFirstChild();child!=null;child=child.getNextSibling())text(child,b,depth+1);if(block)b.append('\n');}
 static BookDocument read(File file)throws Exception{
  BookDocument book=new BookDocument();book.title=file.getName();if(!file.isFile())throw new IOException();
  if(file.getName().toLowerCase(Locale.ROOT).endsWith(".txt")){if(file.length()>2097152)throw new IOException(L.t("TXT peste 2 MiB"));String text;try(InputStream in=new FileInputStream(file)){text=utf8(bytes(in,2097152));}for(int at=0;at<text.length();){int end=Math.min(text.length(),at+12000);if(end<text.length()&&Character.isHighSurrogate(text.charAt(end-1)))end--;book.names.add(L.t("Partea ")+(book.names.size()+1));book.chapters.add(text.substring(at,end));at=end;}if(book.chapters.isEmpty()){book.names.add("Text");book.chapters.add("");}return book;}
  if(!file.getName().toLowerCase(Locale.ROOT).endsWith(".epub")||file.length()>33554432)throw new IOException(L.t("Alege TXT sau EPUB, maximum 32 MiB"));
  try(ZipFile zip=new ZipFile(file)){Set<String> seen=new HashSet<String>();Enumeration<? extends ZipEntry> all=zip.entries();while(all.hasMoreElements()){ZipEntry e=all.nextElement();String n=e.getName();if(seen.size()>=2000||!seen.add(n)||n.startsWith("/")||n.contains("\\")||Arrays.asList(n.split("/")).contains(".."))throw new IOException(L.t("Arhivă EPUB invalidă"));}if(!utf8(entry(zip,"mimetype",64)).trim().equals("application/epub+zip"))throw new IOException(L.t("Tip EPUB invalid"));Document container=xml(entry(zip,"META-INF/container.xml",65536));NodeList roots=container.getElementsByTagNameNS("*","rootfile");if(roots.getLength()==0)throw new IOException();String opf=path("",((Element)roots.item(0)).getAttribute("full-path"));Document pkg=xml(entry(zip,opf,524288));String title=first(pkg,"title");if(!title.isEmpty())book.title=title;HashMap<String,String> manifest=new HashMap<String,String>();NodeList items=pkg.getElementsByTagNameNS("*","item");for(int i=0;i<items.getLength();i++){Element item=(Element)items.item(i);if(item.getAttribute("media-type").equals("application/xhtml+xml"))manifest.put(item.getAttribute("id"),path(opf,item.getAttribute("href")));}NodeList spine=pkg.getElementsByTagNameNS("*","itemref");if(spine.getLength()==0||spine.getLength()>100)throw new IOException(L.t("EPUB fără capitole sau peste 100 capitole"));int total=0;for(int i=0;i<spine.getLength();i++){String name=manifest.get(((Element)spine.item(i)).getAttribute("idref"));if(name==null)throw new IOException(L.t("Capitol EPUB nesuportat"));byte[] raw=entry(zip,name,524288);total+=raw.length;if(total>4194304)throw new IOException(L.t("EPUB depășește 4 MiB de text"));Document chapter=xml(raw);StringBuilder text=new StringBuilder();text(chapter,text,0);String label=first(chapter,"title");book.names.add(label.isEmpty()?L.t("Capitolul ")+(i+1):label);book.chapters.add(text.toString().replaceAll("[ \\t]+"," ").replaceAll("\\n[ \\t]+","\n").replaceAll("\\n{3,}","\n\n").trim());}}
  return book;
 }
}
